  if (admit.created.length) {
    rt4.showToast(
      admit.created.length + " paciente" + (admit.created.length === 1 ? "" : "s") + " agregado" + (admit.created.length === 1 ? "" : "s") + " al censo \u2014 completa ubicaci\xF3n",
      "success"
    );
  }
  var freshBlocks = admit.blocks;
