  updateLabPatientBanner(patient, fechaBanner, rt4.findPatientByRegistro);
  var box = prepareLabOutputBox(fechaBanner, rt4);
  var src = String(result.sourceText || "").trim();
  attachSomeTablesParsed(result, src);
  appendResLabChunksToBox(box, resLabs, src, result, rt4.getLabOutputPrefs(), rt4);
  document.getElementById("lab-output-section").style.display = "block";
  var labRoot = document.getElementById("appcontent-lab");
